+            }
+        }
+        X509_STORE_CTX_cleanup(ctx);
+        if (!TEST_true(X509_VERIFY_PARAM_set1_email(vpm, NULL, 0)))
+            goto err;
+    }
+
+    for (size_t i = 0; multiname_ips[i] != NULL; i++) {
+        /* Try one not in the certificate */
+        if (!TEST_true(X509_VERIFY_PARAM_set1_ip_asc(vpm, "8.8.8.8")))
+            goto err;
