+            if (!f.is_app && f.frame_type != 0)
+                QLOG_U64("trigger_frame_type", f.frame_type);
+            QLOG_STR_LEN("reason", f.reason, f.reason_len);
+        }
+        break;
+    case OSSL_QUIC_FRAME_TYPE_HANDSHAKE_DONE:
+        {
+            if (!ossl_quic_wire_decode_frame_handshake_done(pkt))
+                goto unknown;
+
