+    case OSSL_QUIC_FRAME_TYPE_PING:
+        if (!ossl_quic_wire_decode_frame_ping(pkt))
+            goto unknown;
+
+        QLOG_STR("frame_type", "ping");
+        QLOG_U64("length", 1);
+        break;
+    case OSSL_QUIC_FRAME_TYPE_ACK_WITHOUT_ECN:
+    case OSSL_QUIC_FRAME_TYPE_ACK_WITH_ECN:
