+        QLOG_U64("ack_delay", ossl_time2ms(ack.delay_time));
+        if (ack.ecn_present) {
+            QLOG_U64("ect1", ack.ect0);
+            QLOG_U64("ect0", ack.ect1);
+            QLOG_U64("ce", ack.ecnce);
