+    if (BIO_printf(out, "%*sNames:\n", indent, "") <= 0)
+        return 0;
+    if (OSSL_GENERAL_NAMES_print(out, pointer->name, indent) <= 0)
+        return 0;
+    if (BIO_puts(out, "\n") <= 0)
+        return 0;
+    if (pointer->hash != NULL) {
+        if (BIO_printf(out, "%*sHash:\n", indent, "") <= 0)
+            return 0;
+        if (i2r_HASH(method, pointer->hash, out, indent + 4) <= 0)
+            return 0;
+    }
+    return 1;
+}
+
