+OPENSSL_TARGET_AVX2
+static inline __m256i insert_newlines_by_mask(__m256i data, __m256i mask)
+{
+    __m256i newline = _mm256_set1_epi8('\n');
+
+    return _mm256_or_si256(_mm256_and_si256(mask, newline),
+        _mm256_andnot_si256(mask, data));
+}
