diff --git a/test/test_base64_simdutf.c b/test/test_base64_simdutf.c
new file mode 100644
index 0000000000..a39155dc44
--- /dev/null
+++ b/test/test_base64_simdutf.c
@@ -0,0 +1,255 @@
+/*
